globalThis.KENGURU_CHOICE_LAYOUTS = {"2004-3-4/1":{"options":[{"image":"assets/separated-choice-vectors/2004-3-4/01-1.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/01-2.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/01-3.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/01-4.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/01-5.svg"}],"condition":{"src":"assets/separated-choices/2004-3-4/01-condition.webp","width":126,"height":97}},"2004-3-4/7":{"options":[{"image":"assets/separated-choice-vectors/2004-3-4/07-1.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/07-2.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/07-3.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/07-4.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/07-5.svg"}]},"2004-3-4/9":{"options":[{"text":"1, 2, 3"},{"text":"2, 3, 4"},{"text":"1, 3, 4"},{"text":"1, 2, 4"},{"text":"2, 3, 4"}],"condition":{"src":"assets/separated-choices/2004-3-4/09-condition.webp","width":764,"height":149}},"2004-3-4/18":{"options":[{"image":"assets/separated-choice-vectors/2004-3-4/18-1.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/18-2.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/18-3.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/18-4.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/18-5.svg"}]},"2004-3-4/24":{"options":[{"image":"assets/separated-choice-vectors/2004-3-4/24-1.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/24-2.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/24-3.svg"},{"image":"assets/separated-choice-vectors/2004-3-4/24-4.svg"},{"text":"Все фигуры можно составить"}],"condition":{"src":"assets/separated-choices/2004-3-4/24-condition.webp","width":281,"height":247}}};
globalThis.KENGURU_LEGACY = [[2004,"3–4 классы",[[824,248,"У Гарри Поттера есть волшебные очки, в которых он видит все красное — белым, а все белое — красным. Гарри посмотрел через свои волшебные очки на прямоугольник, изображенный справа. Что он увидел?",{"0":[84.3,216.7,31.3,23.5],"1":[227.9,216.7,31.3,23.5],"2":[367.9,216.7,32.6,23.5],"3":[507.7,216.7,32.6,23.5],"4":[647.7,216.7,31.3,23.5]},"B","Волшебные очки",[["Поменяй цвета","Верхняя строка исходного рисунка слева направо белая, красная, белая, красная. В очках порядок цветов будет обратным."],["Проверь остальные клетки","Во второй строке красной станет только правая клетка, а в третьей — только вторая слева. Все три строки совпадают с рисунком B."]],""],[824,100,"Чему равна сумма двух чисел, если она на 3 больше одного из этих чисел и на 4 больше другого?",{"0":[45.1,68.1,31.3,23.5],"1":[208.3,68.1,31.3,23.5],"2":[354.8,68.1,32.6,23.5],"3":[501.1,68.1,32.6,23.5],"4":[647.7,68.1,31.3,23.5]},"D","Два слагаемых",[["Восстанови числа","Сумма получается, когда к первому числу прибавляют второе. Если сумма на 3 больше первого числа, второе равно 3."],["Вычисли сумму","По тому же правилу первое число равно 4. Вместе получаем 3 + 4 = 7."]],""],[824,181,"На участке дороги идет ремонт. Водителям приходится объезжать этот участок по запасному пути, отмеченному на плане пунктиром. На сколько километров увеличивает путь этот объезд?",{"0":[45.1,149.1,31.3,23.5],"1":[155,149.1,31.3,23.5],"2":[258.3,149.1,32.7,23.5],"3":[364.7,149.1,32.7,23.5],"4":[478.1,149.1,31.3,23.5]},"C","Дорога в объезд",[["Сравни горизонтальные отрезки","Объезд идёт по трём сторонам прямоугольника. Нижний горизонтальный отрезок такой же длины, как закрытый участок сверху."],["Сложи добавленные отрезки","К прежней длине добавились спуск и подъём по 3 км. Получается 3 + 3 = 6 км."]],""],[824,153,"Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?",{"0":[45.1,122.2,31.3,23.5],"1":[208.3,122.2,31.3,23.5],"2":[354.8,122.2,32.6,23.5],"3":[501.2,122.2,32.6,23.5],"4":[647.8,122.2,31.3,23.5]},"D","Шаги по лестнице",[["Посчитай пройденные ступеньки","Первый шаг привёл Серёжу на вторую ступеньку. Дальше он наступал на ступеньки 4, 6, 8 и 10."],["Учти последнюю","После пятого шага осталась ещё одна ступенька. Всего их 10 + 1 = 11."]],""],[824,213,"Какие числа расположены одновременно в прямоугольнике и в круге, но не в треугольнике?",{"0":[45.1,109.5,31.3,23.5],"1":[208.3,109.5,31.3,23.5],"2":[354.8,109.5,32.6,23.5],"3":[45.1,143.5,32.6,23.5],"4":[208.2,143.5,31.3,23.5]},"B","Пересечение фигур",[["Найди общую область","Внутри круга и прямоугольника одновременно находятся 1, 10 и 13."],["Проверь треугольник","Число 13 лежит также внутри треугольника. Снаружи треугольника остаются 1 и 10."]],""],[824,70,"Какое число пропущено: 2004 – 1389 = … – 1489?",{"0":[45.1,41.1,31.3,23.5],"1":[208.3,41.1,31.3,23.5],"2":[354.8,41.1,32.6,23.5],"3":[501.2,41.1,32.6,23.5],"4":[647.8,41.1,31.3,23.5]},"C","Равные разности",[["Сравни вычитаемые","Число 1489 больше числа 1389 на 100. Если вычитать на 100 больше из того же числа, ответ уменьшится на 100."],["Сохрани разность","Увеличь первое число тоже на 100. Получится 2004 + 100 = 2104."]],""],[845,188,"Миша хочет обвести каждую из фигур А – Е фломастером, не отрывая фломастер от листа бумаги и не проводя по одной линии дважды. Какую фигуру он не сможет так обвести?",{"0":[77.8,156.5,31.4,23.5],"1":[194.9,156.5,31.4,23.5],"2":[311.5,156.5,32.7,23.5],"3":[431.4,156.5,32.7,23.5],"4":[594.5,156.5,31.4,23.5]},"C","Рисунок одним штрихом",[["Проверь угол","Когда фломастер приходит в угол по одной линии и уходит по другой, он использует сразу две линии. Угол с нечётным числом линий должен стать началом или концом пути."],["Сосчитай нечётные вершины","У фигуры C из каждого из четырёх углов выходят по три линии. Для четырёх таких углов двух концов пути не хватит."]],""],[845,123,"Разглядывая семейный альбом, Ванечка нашел там фотографии своих двух бабушек и двух дедушек. А сколько бабушек и дедушек имели его бабушки и дедушки все вместе?",{"0":[45.1,91.1,31.3,23.5],"1":[208.3,91.1,31.3,23.5],"2":[354.8,91.1,32.6,23.5],"3":[501.2,91.1,32.6,23.5],"4":[647.8,91.1,31.3,23.5]},"D","Бабушки и дедушки",[["Сосчитай людей на фотографиях","У Ванечки две бабушки и два дедушки. Всего таких родственников четверо."],["Посчитай их бабушек и дедушек","У каждого из них тоже две бабушки и два дедушки. Получается 4 × 4 = 16."]],""],[845,186,"Какие фигурки надо взять, чтобы из них можно было составить круг? 1 2 3 4",{"0":[45.1,154.4,31.3,23.5],"1":[208.3,154.4,31.3,23.5],"2":[354.8,154.4,32.6,23.5],"3":[501.2,154.4,32.6,23.5],"4":[647.8,154.4,31.3,23.5]},"D","Круг из кусочков",[["Найди округлые края","У деталей 1 и 4 есть закруглённые внешние края. Поверни детали так, чтобы эти края образовали внешнюю границу круга, а выемки смотрели внутрь."],["Заполни середину","Деталь 2 входит между ними. Её изогнутая выемка прилегает к округлому выступу детали 1. Нужны детали 1, 2 и 4."]],""],[845,123,"В коридоре детского сада стояли двухколесные и трехколесные велосипеды. Катя подсчитала, что колес – 18, а рулей всего 7. Сколько было двухколесных велосипедов?",{"0":[45.1,91.2,31.3,23.5],"1":[208.3,91.2,31.3,23.5],"2":[354.8,91.2,32.6,23.5],"3":[501.2,91.2,32.6,23.5],"4":[647.8,91.2,31.3,23.5]},"B","Велосипеды и колёса",[["Начни с двух колёс на руль","Семь рулей означают семь велосипедов. Если дать каждому по два колеса, потребуется 7 × 2 = 14 колёс."],["Распредели оставшиеся колёса","Ещё 18 − 14 = 4 колеса достаются четырём трёхколёсным велосипедам. Двухколёсных было 7 − 4 = 3."]],""],[845,149,"Весь класс, в котором учатся Маша и Даша, выстроился в колонну по одному. Позади Маши стоит 16 человек, включая Дашу, а впереди Даши стоит 14 человек. Сколько ребят в классе, если между Машей и Дашей стоит 7 человек?",{"0":[45.1,116.8,31.3,23.5],"1":[208.3,116.8,31.3,23.5],"2":[354.8,116.8,32.6,23.5],"3":[501.3,116.8,32.6,23.5],"4":[647.9,116.8,31.3,23.5]},"C","Школьная колонна",[["Раздели колонну на части","Впереди Даши стоят Маша, семь человек между девочками и те, кто впереди Маши. Значит, перед Машей стоят 14 − 1 − 7 = 6 человек."],["Собери всю колонну","Шесть человек стоят впереди Маши, за ней — шестнадцать. Вместе с самой Машей в классе 6 + 1 + 16 = 23 человека."]],""],[845,311,"Часовщик смотрит на 4 будильника. Только один из этих будильников показывает верное время. Из оставшихся один спешит на 20 минут, другой отстает на 20 минут, а третий вовсе стоит. Какое время показывает правильно идущий будильник?",{"0":[45.1,257.2,31.3,23.5],"1":[286.9,257.2,31.3,23.5],"2":[519.4,257.2,32.6,23.5],"3":[45.1,282.9,32.6,23.5],"4":[286.8,282.9,31.3,23.5]},"B","Четыре будильника",[["Найди показания с равным шагом","Верное время должно быть ровно на 20 минут позже одного показания и на 20 минут раньше другого. На циферблатах такой ряд образуют 4:45, 5:05, 5:25."],["Выбери середину","Между 4:45 и 5:25 находится 5:05. Его показывает правильно идущий будильник."]],""],[824,92,"В некотором месяце 3 воскресенья приходятся на четные числа. На какой день недели приходится 25-е число этого месяца?",{"0":[45.1,60.7,31.3,23.5],"1":[208.4,60.7,31.3,23.5],"2":[354.9,60.7,32.6,23.5],"3":[501.2,60.7,32.6,23.5],"4":[647.9,60.7,31.3,23.5]},"A","Воскресенья в календаре",[["Найди первое воскресенье","Между воскресеньями по семь дней, поэтому чётные и нечётные даты чередуются. Для трёх чётных воскресений всего должно быть пять воскресений, а первое должно быть чётным."],["Перейди к 25-му числу","Первое воскресенье может быть только 2-го числа. Если взять 4-е или позже, пятое воскресенье попадёт на 32-е или позже. Воскресенья идут 2, 9, 16, 23 и 30-го, поэтому 25-е — вторник."]],""],[824,117,"Карина нашла старую книгу, в которой не хватало нескольких страниц. Последняя страница перед потерянной частью имеет номер 24, а первая после нее – 45. Сколько листков выпало из книги?",{"0":[45.1,86.3,31.3,23.5],"1":[208.3,86.3,31.3,23.5],"2":[354.8,86.3,32.6,23.5],"3":[501.2,86.3,32.6,23.5],"4":[647.8,86.3,31.3,23.5]},"B","Выпавшие листы",[["Посчитай страницы","Выпали страницы с 25-й по 44-ю включительно. Их 44 − 25 + 1 = 20."],["Посчитай листы","На каждом листе две страницы. Значит, выпало 20 : 2 = 10 листов."]],""],[824,148,"В каждую клеточку квадрата 2х2 вписано какое-то число. Сумма чисел в верхней строчке равна 3, а в нижней – 8. Чему равна сумма в правом столбике, если сумма чисел левого столбика равна 4?",{"0":[45.1,116.7,31.3,23.5],"1":[164.9,116.7,31.3,23.5],"2":[284.9,116.7,32.6,23.5],"3":[404.6,116.7,32.6,23.5],"4":[524.5,116.7,31.3,23.5]},"C","Суммы в квадрате",[["Сложи суммы строк","Сумма всех четырёх чисел равна 3 + 8 = 11."],["Вычти левый столбец","На левый столбец приходится 4. Значит, в правом столбце сумма равна 11 − 4 = 7."]],""],[824,153,"Во сколько раз миллион миллиардов отличается от миллиарда миллионов?",{"0":[45.1,65.5,31.3,23.5],"1":[354.8,65.5,31.3,23.5],"2":[45.1,93.4,32.6,23.5],"3":[354.8,93.4,32.6,23.5],"4":[45.1,121.4,31.3,23.5]},"D","Миллион миллиардов",[["Запиши два произведения","Миллион миллиардов — это миллион, умноженный на миллиард. Миллиард миллионов — это миллиард, умноженный на миллион."],["Поменяй множители местами","При перестановке множителей произведение остаётся тем же. Оба числа равны."]],""],[824,97,"У Эдварда 2004 фантика. Половина из них синие, четверть – красные, третья часть остальных – зеленые. Сколько у него зеленых фантиков?",{"0":[45.1,65.4,31.3,23.5],"1":[208.3,65.4,31.3,23.5],"2":[354.8,65.4,32.6,23.5],"3":[501.2,65.4,32.6,23.5],"4":[647.8,65.4,31.3,23.5]},"B","Зелёные фантики",[["Найди оставшуюся четверть","Половина — это две четверти. Вместе с красной четвертью это три четверти всех фантиков. Остаётся одна четверть, то есть 2004 : 4 = 501."],["Возьми треть остатка","Зелёных фантиков 501 : 3 = 167."]],""],[824,237,"На каждой грани бумажного кубика написана цифра 1, 2 или 3, причем цифры на противоположных гранях одинаковы. Какая из фигурок может получиться, если этот кубик разрезать по некоторым ребрам и развернуть?",{"0":[77.8,205.4,31.4,23.5],"1":[237.9,205.4,31.4,23.5],"2":[394.5,205.4,32.7,23.5],"3":[557.8,205.4,32.7,23.5],"4":[704.4,205.4,31.4,23.5]},"E","Противоположные грани",[["Сверни полоску в пояс","Четыре квадрата в ряд образуют боковые грани куба. При этом первая грань окажется напротив третьей, а вторая — напротив четвёртой."],["Сверь три пары","В E в ряду стоят 1, 2, 1, 2. Оставшиеся грани с тройками закрывают пояс сверху и снизу. Все три противоположные пары совпадают."]],""],[824,174,"В полдень на детскую площадку пришел Вася, через два часа после него – Маша, а через полтора часа после нее – Никита. Вася играл четыре часа, Маша – три, а Никита – два часа. Как долго Маша и Никита были на площадке вдвоем?",{"0":[45.1,116.8,31.3,23.5],"1":[286.9,116.8,31.3,23.5],"2":[519.3,116.8,32.6,23.5],"3":[45.1,142.5,32.6,23.5],"4":[286.8,142.5,31.3,23.5]},"B","На площадке вдвоём",[["Запиши время прихода и ухода","Вася был на площадке с 12:00 до 16:00, Маша — с 14:00 до 17:00, Никита — с 15:30 до 17:30."],["Найди время без Васи","Маша и Никита остались вдвоём после ухода Васи в 16:00 и до ухода Маши в 17:00. Прошёл один час."]],""],[824,118,"Два ковша воды – это половина ведерка, а три чашки – это половина ковша. Тогда два ведерка – это",{"0":[45.1,65.5,31.3,23.5],"1":[286.9,65.5,31.3,23.5],"2":[519.4,65.5,32.6,23.5],"3":[45.1,91.1,32.6,23.5],"4":[286.9,91.1,31.3,23.5]},"B","Ведёрки, ковши и чашки",[["Переведи в ковши","В половине ведёрка 2 ковша, значит, в целом 4 ковша, а в двух ведёрках — 8."],["Переведи в чашки","В половине ковша 3 чашки, значит, в целом ковше их 6. Восемь ковшей — это 8 × 6 = 48 чашек."]],""],[845,141,"В трех играх чемпионата по футболу команда забила 3 гола и пропустила в свои ворота 1 гол. За каждую победу команда получает 3 очка, за ничью – 1 очко, а за поражение — 0 очков. Сколько очков не могла набрать команда за эти 3 игры?",{"0":[45.1,109,31.3,23.5],"1":[208.3,109,31.3,23.5],"2":[354.8,109,32.6,23.5],"3":[501.2,109,32.6,23.5],"4":[647.8,109,31.3,23.5]},"E","Очки за три матча",[["Проверь три очка","Для трёх очков нужны либо три ничьи, либо победа и два поражения. При трёх ничьих команда забила бы столько же голов, сколько пропустила. При двух поражениях она пропустила бы хотя бы два."],["Приведи примеры остальных итогов","Четыре очка дают счета 3:0, 0:0, 0:1. Пять дают 2:0, 1:1, 0:0. Шесть дают 2:0, 1:0, 0:1. Семь дают 1:0, 1:0, 1:1. Только три очка получить нельзя."]],""],[845,213,"В верхнюю строчку и первый столбец квадратной таблицы (кроме угловой клетки) записали какието числа, и для этих чисел составили таблицу умножения. Потом некоторые числа стерли, а некоторые заменили буквами. Какие две буквы заменяют одно и то же число?",{"0":[45.1,157.6,31.3,23.5],"1":[208.3,157.6,31.3,23.5],"2":[354.8,157.6,32.6,23.5],"3":[45.1,181.9,32.6,23.5],"4":[208.3,181.9,31.3,23.5]},"E","Таблица умножения",[["Восстанови заголовки строк","Число слева от 36 и 8 должно делить оба числа, а число слева от 27 и 6 — делить эти два. В столбце с 8 и 6 заголовок делит и 8, и 6. Это 1 или 2. При 1 заголовок строки был бы 8, но 36 на 8 не делится."],["Сравни буквы","Заголовок столбца равен 2. Тогда заголовок строки с 8 равен 4, и Г = 4 × (18 : 6) = 12. В том же столбце, где стоит 8, буква А равна 6 × 2 = 12."]],""],[845,165,"Длинную нитку сложили вдвое, еще раз вдвое и еще раз вдвое. Получившуюся толстую «нитку» разрезали на две части и разобрали обратно на тонкие ниточки. Оказалось, что две из этих ниточек имеют длины 4 см и 9 см. Какова наименьшая возможная длина исходной нитки?",{"0":[45.1,133.3,31.3,23.5],"1":[208.3,133.3,31.3,23.5],"2":[354.8,133.3,32.6,23.5],"3":[501.1,133.3,32.6,23.5],"4":[647.7,133.3,31.3,23.5]},"B","Сложенная нитка",[["Посмотри на один слой","После трёх сгибов получилось восемь слоёв. Разрез делит каждый слой на части длиной x и y. Если x взять со стороны свободных концов, короткие части у этих концов имеют длину x, а части со сгибом — 2x или 2y."],["Выбери длину слоя","Числа 4 и 9 не могут одновременно быть x и 2x, поэтому одно из них относится к x, а другое к y. Чтобы слой был как можно короче, возьмём два отрезка со сгибами, длиной 2x и 2y. Тогда x + y = 4 : 2 + 9 : 2 = 6,5 см. Вся нитка имеет длину 8 × 6,5 = 52 см."]],""],[845,267,"Каждая из фигурок А – D состоит из 7 кубиков. Какую из них нельзя составить из деталей, изображенных справа?",{"0":[58.2,215.7,31.4,23.5],"1":[168.3,215.7,31.4,23.5],"2":[311.5,215.7,32.7,23.5],"3":[444.8,215.7,32.7,23.5],"4":[544.6,215.7,31.4,23.5]},"E","Фигуры из кубиков",[["Раздели A и B","Для A возьми самую высокую колонку и нижний кубик соседней колонки. Для B возьми весь нижний ряд и средний по высоте кубик крайней колонки. В обоих случаях получается длинный уголок из четырёх кубиков и малый уголок из трёх."],["Раздели C и D","У C малый уголок образуют два верхних кубика слева сзади и самый верхний справа сзади. Остаётся объёмная деталь из четырёх кубиков. У D два верхних кубика высокой колонки и два кубика справа образуют деталь-ступеньку. Оставшиеся три — малый уголок. Значит, собрать можно все четыре фигуры."]],""],[845,167,"В треугольнике отмечены вершины и, кроме того, по одной точке на каждой из сторон. Сколько треугольников с вершинами в отмеченных точках можно построить?",{"0":[45.1,109,31.3,23.5],"1":[208.3,109,31.3,23.5],"2":[354.8,109,32.6,23.5],"3":[45.1,135.7,32.6,23.5],"4":[208.3,135.7,31.3,23.5]},"C","Треугольники из точек",[["Выбери три точки","Из шести точек можно составить 6 × 5 × 4 = 120 списков из трёх различных точек. Один и тот же набор записывается шестью способами, поэтому наборов 120 : 6 = 20."],["Убери наборы на прямой","На каждой стороне большого треугольника есть ровно три отмеченные точки. Из них треугольник не получается. Остаётся 20 − 3 = 17."]],""],[845,116,"Разность двух четырехзначных чисел равна 7. Для каждого из этих чисел Вася вычислил сумму цифр, а потом из большей суммы вычел меньшую. Какой результат он не мог получить?",{"0":[45.1,84.7,31.3,23.5],"1":[208.3,84.7,31.3,23.5],"2":[354.8,84.7,32.6,23.5],"3":[501.2,84.7,32.6,23.5],"4":[647.8,84.7,31.3,23.5]},"D","Суммы цифр",[["Проследи за переносами","От меньшего числа к большему можно перейти прибавлением 7. Без переносов сумма цифр выросла бы на 7. Каждый перенос заменяет десять единиц в одном разряде одной единицей в следующем и уменьшает сумму цифр на 9."],["Перебери число переносов","Возможны 0, 1, 2 или 3 переноса, поскольку оба числа четырёхзначные. Изменения суммы равны 7, −2, −11, −20. После вычитания меньшей суммы из большей получаются 7, 2, 11 и 20. Число 13 получить нельзя."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2004":{"1":{"question":"У Гарри Поттера есть волшебные очки, в которых он видит все красное — белым, а все белое — красным. Гарри посмотрел через свои волшебные очки на прямоугольник, изображенный справа. Что он увидел?","image":"assets/legacy-conditions/2004/task-01.webp","imageWidth":930,"imageHeight":310},"2":{"question":"Чему равна сумма двух чисел, если она на 3 больше одного из этих чисел и на 4 больше другого?","choices":["3","4","5","7","14"]},"3":{"question":"На участке дороги идет ремонт. Водителям приходится объезжать этот участок по запасному пути, отмеченному на плане пунктиром. На сколько километров увеличивает путь этот объезд?","choices":["3 км","5 км","6 км","10 км","невозможно определить"],"image":"assets/legacy-conditions/2004/task-03.webp","imageWidth":348,"imageHeight":143},"4":{"question":"Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?","choices":["5","7","9","11","12"]},"5":{"question":"Какие числа расположены одновременно в прямоугольнике и в круге, но не в треугольнике?","choices":["5 и 11","1 и 10","13","3 и 9","6,7 и 4"],"image":"assets/legacy-conditions/2004/task-05.webp","imageWidth":313,"imageHeight":271},"6":{"question":"Какое число пропущено: 2004 – 1389 = … – 1489?","choices":["1994","1995","2104","615","1904"]},"7":{"question":"Миша хочет обвести каждую из фигур А – Е фломастером, не отрывая фломастер от листа бумаги и не проводя по одной линии дважды. Какую фигуру он не сможет так обвести?","image":"assets/legacy-conditions/2004/task-07.webp","imageWidth":812,"imageHeight":131},"8":{"question":"Разглядывая семейный альбом, Ванечка нашел там фотографии своих двух бабушек и двух дедушек. А сколько бабушек и дедушек имели его бабушки и дедушки все вместе?","choices":["4","8","10","16","32"]},"9":{"question":"Какие фигурки надо взять, чтобы из них можно было составить круг?","image":"assets/legacy-conditions/2004/task-09.webp","imageWidth":912,"imageHeight":201},"10":{"question":"В коридоре детского сада стояли двухколесные и трехколесные велосипеды. Катя подсчитала, что колес – 18, а рулей всего 7. Сколько было двухколесных велосипедов?","choices":["2","3","4","5","6"]},"11":{"question":"Весь класс, в котором учатся Маша и Даша, выстроился в колонну по одному. Позади Маши стоит 16 человек, включая Дашу, а впереди Даши стоит 14 человек. Сколько ребят в классе, если между Машей и Дашей стоит 7 человек?","choices":["37","30","23","22","365"]},"12":{"question":"Часовщик смотрит на 4 будильника. Только один из этих будильников показывает верное время. Из оставшихся один спешит на 20 минут, другой отстает на 20 минут, а третий вовсе стоит. Какое время показывает правильно идущий будильник?","choices":["4 час 45 мин","5 час 5 мин","5 час 25 мин","5 час 40 мин","невозможно определить"],"image":"assets/legacy-conditions/2004/task-12.webp","imageWidth":815,"imageHeight":169},"13":{"question":"В некотором месяце 3 воскресенья приходятся на четные числа. На какой день недели приходится 25-е число этого месяца?","choices":["вторник","среда","четверг","пятница","суббота"]},"14":{"question":"Карина нашла старую книгу, в которой не хватало нескольких страниц. Последняя страница перед потерянной частью имеет номер 24, а первая после нее – 45. Сколько листков выпало из книги?","choices":["9","10","11","20","21"]},"15":{"question":"В каждую клеточку квадрата 2х2 вписано какое-то число. Сумма чисел в верхней строчке равна 3, а в нижней – 8. Чему равна сумма в правом столбике, если сумма чисел левого столбика равна 4?","choices":["4","6","7","8","11"],"image":"assets/legacy-conditions/2004/task-15.svg","imageWidth":220,"imageHeight":220},"16":{"question":"Во сколько раз миллион миллиардов отличается от миллиарда миллионов?","choices":["в миллион раз больше","в миллиард раз больше","в тысячу раз меньше","эти числа равны","в сто раз меньше"]},"17":{"question":"У Эдварда 2004 фантика. Половина из них синие, четверть – красные, третья часть остальных – зеленые. Сколько у него зеленых фантиков?","choices":["0","167","501","668","1002"]},"18":{"question":"На каждой грани бумажного кубика написана цифра 1, 2 или 3, причем цифры на противоположных гранях одинаковы. Какая из фигурок может получиться, если этот кубик разрезать по некоторым ребрам и развернуть?","image":"assets/legacy-conditions/2004/task-18.webp","imageWidth":945,"imageHeight":164},"19":{"question":"В полдень на детскую площадку пришел Вася, через два часа после него – Маша, а через полтора часа после нее – Никита. Вася играл четыре часа, Маша – три, а Никита – два часа. Как долго Маша и Никита были на площадке вдвоем?","choices":["полчаса","один час","полтора часа","два часа","три часа"]},"20":{"question":"Два ковша воды — это половина ведерка, а три чашки — это половина ковша. Тогда два ведерка — это","choices":["24 чашки","48 чашек","12 чашек","36 чашек","72 чашки"]},"21":{"question":"В трех играх чемпионата по футболу команда забила 3 гола и пропустила в свои ворота 1 гол. За каждую победу команда получает 3 очка, за ничью – 1 очко, а за поражение — 0 очков. Сколько очков не могла набрать команда за эти 3 игры?","choices":["7","6","5","4","3"]},"22":{"question":"В верхнюю строчку и первый столбец квадратной таблицы (кроме угловой клетки) записали какието числа, и для этих чисел составили таблицу умножения. Потом некоторые числа стерли, а некоторые заменили буквами. Какие две буквы заменяют одно и то же число?","choices":["Е и Н","Р и У","Т и А","Е и Я","Г и А"],"image":"assets/legacy-conditions/2004/task-22.svg","imageWidth":230,"imageHeight":229},"23":{"question":"Длинную нитку сложили вдвое, еще раз вдвое и еще раз вдвое. Получившуюся толстую «нитку» разрезали на две части и разобрали обратно на тонкие ниточки. Оказалось, что две из этих ниточек имеют длины 4 см и 9 см. Какова наименьшая возможная длина исходной нитки?","choices":["48 см","52 см","56 см","64 см","68 см"]},"24":{"question":"Каждая из фигурок А – D состоит из 7 кубиков. Какую из них нельзя составить из деталей, изображенных справа?","image":"assets/legacy-conditions/2004/task-24.webp","imageWidth":954,"imageHeight":339},"25":{"question":"В треугольнике отмечены вершины и, кроме того, по одной точке на каждой из сторон. Сколько треугольников с вершинами в отмеченных точках можно построить?","choices":["5","10","17","20","21"],"image":"assets/legacy-conditions/2004/task-25.webp","imageWidth":259,"imageHeight":194},"26":{"question":"Разность двух четырехзначных чисел равна 7. Для каждого из этих чисел Вася вычислил сумму цифр, а потом из большей суммы вычел меньшую. Какой результат он не мог получить?","choices":["2","7","11","13","20"]}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'assets/kenguru';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, figure) {
    const [url, w, h] = figure;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="16 21 65 62" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, figure) {
    const [url, w, h] = figure;
    const sources = [[7, 43], [57, 57], [123, 60], [193, 56], [253, 53], [313, 62], [380, 58]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      const letterWidth = sw * 77 / 100;
      drawing += crop(url, w, h, [sx, 3, sw, 100], x + (85 - letterWidth) / 2, 30, letterWidth, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask?.question ? authoredTask : imported ?? authoredTask;
      const figure = native === imported && imported?.image
        ? [imported.image, imported.imageWidth, imported.imageHeight] : null;
      const illustration = figure
        ? svg(imported.imageWidth, imported.imageHeight, authoredTask?.illustration ?? 'Рисунки и варианты из условия',
            image(escape(imported.image), imported.imageWidth, imported.imageHeight))
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: figure?.[0],
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask?.crop) {
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, figure ?? card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers${year === 2017 ? '-reviewed' : ''}.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

